const cfg = $input.item.json;
const category = cfg.category;

const queries = [
  `best ${category} 2026`,
  `top ${category} to buy`,
  `${category} buying guide reviews`,
  `${category} models compared`
];

const seen = new Map();
for (const q of queries) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: 'http://searxng:8080/search',
      qs: { format: 'json', language: 'en', q },
      json: true
    });
    for (const r of (res.results || []).slice(0, 12)) {
      if (!seen.has(r.url)) {
        seen.set(r.url, { title: r.title, url: r.url, content: (r.content || '').slice(0, 400) });
      }
    }
  } catch (e) {
    // one query failing shouldn't kill discovery - just yields fewer candidates
  }
}

return [{
  json: {
    ...cfg,
    candidate_pages: Array.from(seen.values())
  }
}];

const cfg = $input.item.json;

const system_prompt = `You are a product research assistant compiling a shortlist of real, currently-sold products for an affiliate review site.

You will be given real web search results (title/url/snippet) about a product category.

Rules:
1. Extract ONLY real products that are actually named/mentioned in the given search results - never invent a product.
2. Return exactly ${cfg.product_count} products if that many distinct real products appear in the results; if fewer genuinely distinct products are mentioned, return as many as you can find (never pad with duplicates or invented items).
3. Each product must be a specific, buyable model (brand + model name), not a generic category description.
4. Products must be UNIQUE - do not list the same base model twice (e.g. two colour variants of the same model count as ONE product; pick the more prominently mentioned one).
5. For each product, pick a source_url that is EXACTLY one of the URLs given to you below (copy it verbatim) - never invent or modify a URL. Prefer a URL whose page is actually about that specific product.
6. Include your best guess at the brand name for each product, extracted from the text given.
7. Output JSON only, matching the schema.`;

const user_prompt = `CATEGORY: ${cfg.category}

SEARCH RESULTS:
${JSON.stringify(cfg.candidate_pages)}

Compile the shortlist now.`;

const discovery_schema = {
  type: "object",
  properties: {
    products: {
      type: "array",
      items: {
        type: "object",
        properties: {
          product_name: { type: "string" },
          brand: { type: "string" },
          source_url: { type: "string" }
        },
        required: ["product_name", "brand", "source_url"]
      }
    }
  },
  required: ["products"]
};

return [{
  json: {
    ...cfg,
    discovery_system_prompt: system_prompt + `\n\nReturn ONLY a JSON object matching exactly this schema - no markdown fences, no extra commentary:\n${JSON.stringify(discovery_schema)}`,
    discovery_user_prompt: user_prompt,
    discovery_schema
  }
}];

const res = $input.item.json;
const raw = (res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content) || (res.message && res.message.content) || res.response || '';

let parsed = null, parseError = null;
try { parsed = JSON.parse(raw); } catch (e) { parseError = e.message; }

const cfg = $('Config').item.json;
const candidateUrls = new Set(($('Search Category Candidates').item.json.candidate_pages || []).map(p => p.url));

let products = (parsed && Array.isArray(parsed.products)) ? parsed.products : [];

// Dedup by normalized product name (strip punctuation/case) - keeps first occurrence.
const seenNames = new Set();
const deduped = [];
for (const p of products) {
  if (!p.product_name) continue;
  const norm = p.product_name.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  if (seenNames.has(norm)) continue;
  // Only trust source URLs that were actually in the real search results - never a model-invented URL.
  if (!p.source_url || !candidateUrls.has(p.source_url)) continue;
  seenNames.add(norm);
  deduped.push({
    product_name: p.product_name,
    brand: p.brand || '',
    category: cfg.category,
    source_url: p.source_url
  });
  if (deduped.length >= cfg.product_count) break;
}

const carried = {
  ollama_base_url: cfg.ollama_base_url,
  research_model: cfg.research_model,
  writer_model: cfg.writer_model,
  qa_model: cfg.qa_model,
  qa_min_confidence: cfg.qa_min_confidence,
  wp_api_url: cfg.wp_api_url,
  wp_api_key: cfg.wp_api_key
};

if (deduped.length === 0) {
  return [{ json: { ...carried, _discoveryError: `No usable products extracted (parseError=${parseError || 'none'})`, product_name: null } }];
}

return deduped.map(p => ({ json: { ...carried, ...p } }));

const item = $input.item.json;
const product = item.product || {};
const category = $('Config').item.json.category;

// Openverse indexes CC-licensed stock/wiki media, not official product photography -
// an exact "Brand Model Number" query routinely returns zero results for anything
// recent (confirmed live: "Apple AirPods Pro 3" -> 0 results, "AirPods Pro" -> 137).
// Fall back progressively to a category-representative photo rather than publishing
// with no image at all, same tradeoff the earlier manual photo pass documented.
//
// Relevance gate: a bare brand-name fallback query can match totally unrelated CC
// media that happens to share the brand's name as a word (confirmed live incident -
// "Anker" matched Wikimedia photos of Anker Jorgensen, a former Danish Prime
// Minister, instead of the Anker electronics brand). Every candidate result is
// checked against the brand/product tokens before it's trusted; a query tier that
// returns results but none relevant falls through to the next tier instead of
// accepting the top hit blindly.
function dedupWords(s) {
  const seen = new Set();
  return (s || '').split(/\s+/).filter(w => {
    const k = w.toLowerCase();
    if (!w || seen.has(k)) return false;
    seen.add(k);
    return true;
  }).join(' ');
}

const candidates = [
  dedupWords(`${product.brand || ''} ${product.name || ''}`),
  product.name,
  product.brand ? `${product.brand} ${category || ''}`.trim() : null,
  category
].filter(Boolean);

function toCredit(pick) {
  const license = (pick.license || '').toUpperCase();
  return `${pick.creator || 'Unknown creator'} · ${license}${pick.license_version ? ' ' + pick.license_version : ''} · via Openverse`;
}

function isRelevant(pick) {
  if (!product.brand) return true;
  const haystack = `${pick.title || ''} ${(pick.tags || []).map(t => t.name || t).join(' ')}`.toLowerCase();
  return haystack.includes(product.brand.toLowerCase());
}

let imageUrl = null, credit = null;
let galleryUrls = []; // [{url, credit}], additional photos beyond the featured one - "a few hero photos"
for (const query of candidates) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.openverse.org/v1/images/',
      qs: { q: query, license_type: 'commercial,modification', page_size: 8 },
      headers: { 'User-Agent': 'ReviewGeekHub-ContentPipeline/1.0 (local affiliate content pipeline)' },
      json: true
    });
    const results = (res.results || []).filter(r => r.url);
    const relevant = results.filter(isRelevant);
    if (relevant.length) {
      imageUrl = relevant[0].url;
      credit = toCredit(relevant[0]);
      // Pull up to 3 more relevant results from the SAME successful query - same tier
      // means same relevance level, mixing tiers would put an exact-match photo next
      // to an unrelated category-filler one in the same gallery.
      galleryUrls = relevant.slice(1, 4).map(r => ({ url: r.url, credit: toCredit(r) }));
      break;
    }
  } catch (e) {
    // try the next, broader candidate
  }
}
// No photo is still not fatal even after exhausting fallbacks - the post publishes
// without a featured image rather than publishing a wrong one.

return [{ json: { ...item, image_url: imageUrl, image_credit: credit, gallery_image_urls: galleryUrls } }];

const item = $input.item.json;
const product = item.product || {};
const query = `${product.brand || ''} ${product.name || ''} official video`.replace(/\s+/g, ' ').trim();

let videoUrl = null;
try {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://searxng:8080/search',
    qs: { format: 'json', language: 'en', q: `${query} site:youtube.com` },
    json: true
  });
  const results = res.results || [];
  const ytWatch = r => /youtube\.com\/watch\?v=[A-Za-z0-9_-]{11}/.test(r.url || '');
  // Prefer a result that actually looks official (brand name + "official"/manufacturer
  // channel wording in the title) over just the first YouTube hit - never fabricate a
  // video, only use a real URL that was actually returned by the search.
  const brand = (product.brand || '').toLowerCase();
  const officialPick = results.find(r => ytWatch(r) && brand && (r.title || '').toLowerCase().includes(brand) && /official/i.test(r.title || ''));
  const anyPick = results.find(ytWatch);
  const pick = officialPick || anyPick;
  if (pick) { videoUrl = pick.url; }
} catch (e) {
  // No video found is not fatal - just skip the video section on the post.
}

return [{ json: { ...item, video_url: videoUrl } }];

function slugify(s) {
  return (s || '').toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

// Deterministic safety net: the writer prompt tells the model never to put raw
// evidence ids in reader-facing prose, but a local model complies inconsistently
// (confirmed on a real run - one product came back clean, the sibling product in
// the same batch still wrote "...treble and muted mids. (SENT-002)"). Prompting
// alone isn't reliable enough for something this visible on a live page, so strip
// any surviving id pattern outright before publishing, regardless of what the
// model produced.
function stripCitations(s) {
  if (!s || typeof s !== 'string') return s;
  return s
    // Strips an entire (...)/[...] group made up of one or more FACT-N/EXP-N/SENT-N
    // tokens, however they're separated (comma, semicolon, "and", etc) - covers both
    // single citations "(SENT-002)" and compound ones "[FACT-003; EXP-002]".
    .replace(/\s*[\(\[]\s*(?:(?:FACT|EXP|SENT)-\d+[\s,;&]*(?:and)?[\s,;]*)+[\)\]]/gi, '')
    .replace(/\s+([.,;:!?])/g, '$1')
    .trim();
}
function stripCitationsArr(arr) {
  return (arr || []).map(stripCitations);
}

const item = $input.item.json;
const review = item;
const product = item.product || {};
const research = $('Parse QA JSON').item.json.research || {};

const content_sections = [];
if (review.expert_consensus) content_sections.push({ heading: 'What the experts found', content: stripCitations(review.expert_consensus) });
for (const s of (review.sections || [])) {
  if (s && s.content) content_sections.push({ heading: s.heading, content: stripCitations(s.content) });
}
if (review.owner_consensus) content_sections.push({ heading: 'What owners say', content: stripCitations(review.owner_consensus) });

const sourceNames = new Set([
  ...(research.facts || []).map(f => f.source_name),
  ...(research.expert_findings || []).map(f => f.source_name),
  ...(research.owner_sentiment || []).map(f => f.source_name)
].filter(Boolean));

const officialUrl = (research.facts && research.facts[0] && research.facts[0].source_url) || product.source_url || null;

const pros = stripCitationsArr(review.pros);
const cons = stripCitationsArr(review.cons);

const productName = item.product_name || product.name || '';
const imageAlt = productName ? `${productName} product photo` : '';

const payload = {
  product_key: slugify(`${product.brand || ''}-${product.name || product.model || ''}`) || slugify(review.title),
  title: stripCitations(review.title || review.seo_title || product.name),
  seo_title: stripCitations(review.seo_title || ''),
  meta_description: stripCitations(review.meta_description || ''),
  focus_keyword: (review.focus_keyword || '').trim(),
  product_name: productName,
  category: product.category,
  excerpt: stripCitations(review.summary || review.meta_description || ''),
  image_url: item.image_url || null,
  image_alt: imageAlt,
  image_credit: item.image_credit || null,
  gallery_image_urls: (item.gallery_image_urls || []).map(g => ({ ...g, alt: imageAlt })),
  video_url: item.video_url || null,
  source_url: officialUrl,
  score: review.score,
  review_count: (research.owner_sentiment || []).length,
  sources: Array.from(sourceNames).join(', '),
  pros,
  cons,
  aspect_chips: [
    ...(pros.slice(0, 3).map(p => ({ label: p.split(' ').slice(0, 4).join(' '), sentiment: 'good' }))),
    ...(cons.slice(0, 2).map(c => ({ label: c.split(' ').slice(0, 4).join(' '), sentiment: 'mixed' })))
  ],
  verdict: stripCitations(review.verdict),
  best_for: stripCitations(review.best_for),
  not_best_for: stripCitations(review.not_best_for),
  content_sections,
  faq: (review.faq || []).map(qa => ({ question: stripCitations(qa.question), answer: stripCitations(qa.answer) })),
  alternatives: (review.alternatives || []).map(a => ({ name: a.name, reason: stripCitations(a.reason) })),
  seo_score: item.seo_score,
  status: 'publish'
};

return [{ json: { ...item, publish_payload: payload } }];

const cfg = $input.item.json;
const research = cfg.research;

const system_prompt = `You are an evidence-based, SEO-aware product review writer for an affiliate review blog.

Your job is to transform VERIFIED PRODUCT RESEARCH into a useful, accurate, search-optimized product review that genuinely helps someone decide whether to buy.

STRICT CONTENT RULES:
1. Use ONLY information supplied in the research data.
2. Do not invent specifications, features, prices, test results, experiences, opinions, or alternative products.
3. Do not claim that you personally tested or used the product.
4. Do not say "we tested" unless the supplied evidence explicitly states our organization performed the test.
5. Do not convert manufacturer claims into independently verified facts.
6. Clearly distinguish: manufacturer claims, independent testing, owner/user opinions.
7. If evidence is conflicting, acknowledge the conflict.
8. If there is insufficient evidence for a claim, do not make the claim.
9. Do not fabricate citations or evidence IDs - every evidence_ids entry in a section or FAQ answer MUST be one of the ids supplied in the research data below.
10. Do not mention information that is not supported by the input.
11. Some independent-test evidence may be drawn from a closely related sibling model rather than the exact product being reviewed (this will be stated in that evidence item's source). When you use such evidence, say so in the text explicitly.
12. When owner sentiment is based on very few reports (check the research data - if there is only one or two owner_sentiment items on a topic), phrase it as an individual report ("one owner reported...") rather than a generalization ("customers report...", "many users say...", "buyers love..."). Never generalize a single anecdote into a broad claim.

SEO AND STRUCTURE RULES:
13. Write "seo_title": a concise, keyword-rich title that includes the exact product name and the word "Review", 60 characters or fewer.
14. Write "meta_description": a compelling search-snippet summary, 150-160 characters, including the product name and its primary use case.
15. Write "best_for" and "not_best_for": one sentence each, describing the ideal buyer and who should skip this product, grounded only in supplied evidence.
16. Write a "faq" array of 3 to 5 realistic buyer questions with answers. Answer ONLY using facts already present in the supplied evidence, and cite evidence_ids the same way as in "sections". If you lack evidence to answer a common buyer question, do not include that question.
17. Write an "alternatives" array using ONLY the alternative products supplied in the research data's "alternatives" field - never invent alternative products. For each, give a one-sentence reason someone might choose it instead, and its evidence_ids where applicable (use an empty array if the research item had no evidence id, since alternatives are supplied directly, not id-tagged - just omit evidence_ids requirement for this field).
18. Your "verdict" must give a clear, decisive recommendation grounded in the evidence (e.g. "Buy this if you need X. Skip it if you need Y."). Do NOT use vague hedging phrases such as "may want to consider", "could be a good option", "worth considering", "appears to be", "seems to be", "might be a good fit".
19. Never write an evidence id (e.g. "EXP-001", "FACT-002", "SENT-003") directly inside reader-facing prose - not in pros, cons, summary, verdict, best_for, not_best_for, or section/FAQ body text. Evidence ids belong ONLY in the dedicated evidence_ids arrays. Readers should never see a bracketed id like "[EXP-001]" on the page.
20. Write "focus_keyword": the exact short phrase a real shopper would type into a search engine for this product review (e.g. "sony wf-1000xm6 review"), lowercase, no punctuation, 2-6 words.

VOICE - EDITORIAL 'WE' VOICE, WRITTEN LIKE A REAL PERSON, NOT AN AI:
- Write in first-person-plural editorial voice throughout: 'we found', 'our take', 'we'd recommend', 'in our research'. This 'we' is the editorial team synthesizing the evidence below - it never means you personally tested or used the product. Never write 'we tested', 'we tried', or 'in our testing' unless the supplied evidence explicitly states our organization performed that test.
- Attribute expert findings and owner sentiment to their real source in the prose (e.g. 'One long-term owner on [source] said...', 'Testing by [source] found...'), instead of presenting evidence as an anonymous fact. Never invent a name or outlet not in the supplied evidence. When sentiment rests on only one or two reports, phrase it as an individual report rather than a broad generalization.
- BANNED WORDS AND PHRASES - never use any of these AI-review cliches: boasts, elevate, seamless, seamlessly, game-changer, game changer, unparalleled, unleash, dive into, delve into, navigate the, landscape (as in 'the smartphone landscape'), realm, testament to, plethora, myriad, robust, cutting-edge, revolutionize, revolutionary, 'whether you're a beginner or a pro' or any 'whether you're X or Y' construction, at the end of the day, 'in today's fast-paced world' or any 'in today's ... world' construction, in conclusion, it's important to note that, it's worth noting that, that being said, needless to say, look no further, packed with features, stands out from the competition, sets it apart, a true testament, 'when it comes to' as a section opener.
- BANNED STRUCTURE - never open the review or any section with a rhetorical question. Never open with 'Let's dive in' or 'Let's take a look'. Never end a section with a paragraph that starts 'Overall,'. Do not open more than one section with the same sentence template (e.g. do not start every section with 'The [product] offers...' or 'One of the standout features is...').
- Vary sentence length and rhythm on purpose - mix short, blunt sentences with longer ones. Do not use the same X, Y, and Z three-item list construction in almost every paragraph.
- Every sentence must carry real, specific information from the evidence, not vague praise or padding. If a sentence could apply to any product in the category, cut it or make it specific.
- Confident does NOT mean comparative or superlative. Never write 'the biggest', 'the largest', 'the best', 'the first', 'the only', or any other superlative/comparative claim (e.g. 'the biggest phone Samsung shipped that year', 'the largest display in the lineup') unless a supplied evidence item explicitly states that exact comparison. State the single fact confidently instead (e.g. 'the display is 6.9 inches at 120Hz') rather than inventing an unstated ranking.
- Never generalize a single-source citation into a plural ('owners say', 'buyers report', 'a feature that disappeared from later phones') - if only one evidence item supports a point, say 'one owner reported' every time it comes up, not just on first mention.
- Never state a specific number, limit, or capacity beyond what the evidence actually gives (e.g. if an owner report mentions using a 1TB card, do not state that as the device's maximum supported capacity unless a source says so).

The final output MUST be valid JSON matching the requested schema. Do not output Markdown. Do not output explanations outside the JSON.`;

const user_prompt = `Create a product review from the following verified research.

PRODUCT:
${JSON.stringify(research.product)}

VERIFIED FACTS:
${JSON.stringify(research.facts)}

EXPERT FINDINGS:
${JSON.stringify(research.expert_findings)}

OWNER SENTIMENT:
${JSON.stringify(research.owner_sentiment)}

REAL ALTERNATIVE PRODUCTS (use only these, do not invent others):
${JSON.stringify(research.alternatives)}

Return the review using the exact JSON schema provided in the format parameter.`;

const review_schema = {
  type: "object",
  properties: {
    seo_title: { type: "string" },
    meta_description: { type: "string" },
    focus_keyword: { type: "string" },
    title: { type: "string" },
    summary: { type: "string" },
    score: { type: "number" },
    best_for: { type: "string" },
    not_best_for: { type: "string" },
    pros: { type: "array", items: { type: "string" } },
    cons: { type: "array", items: { type: "string" } },
    expert_consensus: { type: "string" },
    owner_consensus: { type: "string" },
    verdict: { type: "string" },
    sections: {
      type: "array",
      items: {
        type: "object",
        properties: {
          heading: { type: "string" },
          content: { type: "string" },
          evidence_ids: { type: "array", items: { type: "string" } }
        },
        required: ["heading", "content", "evidence_ids"]
      }
    },
    faq: {
      type: "array",
      items: {
        type: "object",
        properties: {
          question: { type: "string" },
          answer: { type: "string" },
          evidence_ids: { type: "array", items: { type: "string" } }
        },
        required: ["question", "answer", "evidence_ids"]
      }
    },
    alternatives: {
      type: "array",
      items: {
        type: "object",
        properties: {
          name: { type: "string" },
          reason: { type: "string" }
        },
        required: ["name", "reason"]
      }
    }
  },
  required: ["seo_title", "meta_description", "focus_keyword", "title", "summary", "score", "best_for", "not_best_for", "pros", "cons", "verdict", "sections", "faq", "alternatives"]
};

const qa_system_prompt = `You are a strict fact-checking and SEO-quality editor.

Review the generated product review against the supplied evidence.

For every factual claim:
1. Determine whether evidence exists.
2. Determine whether the claim accurately represents the evidence.
3. Detect unsupported claims.
4. Detect invented specifications.
5. Detect invented personal experience.
6. Detect claims that incorrectly present manufacturer statements as independent testing.
7. Detect contradictions.
8. Detect any evidence sourced from a sibling/related model that is presented as if it were tested on the exact product being reviewed, without disclosing the distinction.
9. Detect any case where sentiment based on very few reports (fewer than 3 sources in the evidence) is generalized as if it reflects most/all customers (e.g. "customers report" or "buyers love" when only one or two anecdotes exist in the evidence).
10. Detect vague, hedging verdict language (e.g. "may want to consider", "could be a good option", "worth considering") instead of a clear buy/skip recommendation.
11. Detect any alternative product mentioned that does not appear in the supplied research alternatives list.
12. Detect any FAQ answer not grounded in the supplied evidence.

Return JSON only, matching the requested schema.`;

const qa_schema = {
  type: "object",
  properties: {
    status: { type: "string", enum: ["PASS", "FAIL"] },
    confidence: { type: "number" },
    issues: {
      type: "array",
      items: {
        type: "object",
        properties: {
          type: { type: "string" },
          text: { type: "string" },
          reason: { type: "string" }
        }
      }
    }
  },
  required: ["status", "confidence", "issues"]
};

return [{
  json: {
    ...cfg,
    system_prompt: system_prompt + `\n\nReturn ONLY a JSON object matching exactly this schema - no markdown fences, no extra commentary:\n${JSON.stringify(review_schema)}`,
    user_prompt,
    review_schema,
    qa_system_prompt: qa_system_prompt + `\n\nReturn ONLY a JSON object matching exactly this schema - no markdown fences, no extra commentary:\n${JSON.stringify(qa_schema)}`,
    qa_schema
  }
}];

const res = $input.item.json;
const raw = (res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content) || (res.message && res.message.content) || res.response || '';

let review = null;
let parseError = null;
try {
  review = JSON.parse(raw);
} catch (e) {
  parseError = e.message;
}

const prep = $('Prepare Prompts').item.json;

let retryCount = 0;
try {
  retryCount = $('Retry Writer').item.json._retryCount;
} catch (e) {
  retryCount = 0;
}

let qaRetryCount = 0;
try {
  qaRetryCount = $('Retry Writer After QA').item.json._qaRetryCount;
} catch (e) {
  qaRetryCount = 0;
}

return [{
  json: {
    review,
    _parseOk: review !== null,
    _parseError: parseError,
    research: prep.research,
    ollama_base_url: prep.ollama_base_url,
    writer_model: prep.writer_model,
    qa_model: prep.qa_model,
    qa_min_confidence: prep.qa_min_confidence,
    system_prompt: prep.system_prompt,
    user_prompt: prep.user_prompt,
    review_schema: prep.review_schema,
    qa_system_prompt: prep.qa_system_prompt,
    qa_schema: prep.qa_schema,
    _retryCount: retryCount,
    _qaRetryCount: qaRetryCount
  }
}];

const item = $input.item.json;
const errors = [];

if (!item._parseOk) {
  errors.push(`Writer output was not valid JSON: ${item._parseError}`);
}

const review = item.review;
const required = ["seo_title", "meta_description", "title", "summary", "pros", "cons", "verdict", "sections", "faq", "alternatives", "best_for", "not_best_for"];

if (review) {
  for (const field of required) {
    if (!(field in review)) errors.push(`Missing field: ${field}`);
  }
  if (review.pros && !Array.isArray(review.pros)) errors.push("pros must be an array");
  if (review.cons && !Array.isArray(review.cons)) errors.push("cons must be an array");
  if ("score" in review && typeof review.score !== "number") errors.push("score must be numeric");

  if (review.seo_title && review.seo_title.length > 60) {
