try { seoQa = JSON.parse(raw); } catch (e) { parseError = e.message; }

const prep = $('Prepare SEO QA Prompt').item.json;
const qaScore = seoQa ? seoQa.seo_score : 0;
const finalScore = Math.round((prep.seo_deterministic_score + qaScore) / 2);

return [{
  json: {
    ...prep,
    seo_qa: seoQa,
    _seoQaParseOk: seoQa !== null,
    seo_score: finalScore,
    _seoGreen: prep._seoDeterministicPassed && seoQa !== null && qaScore >= 90 && seoQa.agentic_search_ready === true
  }
}];

const item = $input.item.json;
const failedChecks = (item.seo_checks || []).filter(c => !c.passed).map(c => `- ${c.name}: ${c.detail}`).join('\n') || 'none (deterministic checks passed, but the editor judged the copy weak)';
const editorFeedback = item.seo_qa ? item.seo_qa.feedback : '';

const fix_system_prompt = `You write SEO title and meta description tags for product review pages, optimized for Google and for AI/agentic answer engines that quote short passages directly.

Rules:
- seo_title: <=60 characters, includes the product name and the word "Review", front-loads the primary keyword.
- meta_description: 120-160 characters, includes the product name and a concrete, specific reason to click - it must work as a correct, self-contained answer if quoted directly.
- focus_keyword: the exact short phrase a shopper would search, lowercase, 2-6 words.
- Base everything only on the review content supplied. Do not invent facts. No Markdown.

Return JSON only, matching the schema.`;

const fix_user_prompt = `PRODUCT: ${item.product_name}
VERDICT: ${item.review.verdict}
SUMMARY: ${item.review.summary}

PREVIOUS ATTEMPT:
seo_title: ${item.review.seo_title}
meta_description: ${item.review.meta_description}
focus_keyword: ${item.review.focus_keyword}

PROBLEMS TO FIX:
${failedChecks}
${editorFeedback ? 'Editor feedback: ' + editorFeedback : ''}

Write corrected seo_title, meta_description and focus_keyword that fix these specific problems.`;

const fix_schema = {
  type: "object",
  properties: {
    seo_title: { type: "string" },
    meta_description: { type: "string" },
    focus_keyword: { type: "string" }
  },
  required: ["seo_title", "meta_description", "focus_keyword"]
};

return [{
  json: {
    ...item,
    fix_system_prompt: fix_system_prompt + `\n\nReturn ONLY a JSON object matching exactly this schema - no markdown fences, no extra commentary:\n${JSON.stringify(fix_schema)}`,
    fix_user_prompt,
    fix_schema,
    _seoRetryCount: (item._seoRetryCount || 0) + 1
  }
}];

const res = $input.item.json;
const raw = (res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content) || (res.message && res.message.content) || res.response || '';
let fixed = null;
try { fixed = JSON.parse(raw); } catch (e) { fixed = null; }

const prep = $('Prepare SEO Fix Prompt').item.json;
const updatedReview = fixed ? { ...prep.review, ...fixed } : prep.review;

return [{
  json: {
    ...prep,
    review: updatedReview
  }
}];
